(()=>{'use strict';
const A=RepoAccount,U=RepoAdminUI,slot=document.querySelector('#x-collection-settings');let epoch=0,settings=null,scanPending=false,progressPending=false,requestedAt=null;
async function load(){if(!A.user?.admin)return;const token=++epoch;
try{const data=await A.request('/api/editorial?action=x-settings');if(token!==epoch||!A.user?.admin)return;settings=data.settings;
slot.innerHTML=`<form id="x-collection-form"><label class="publish-control"><input id="x-collection-enabled" type="checkbox" ${settings.enabled?'checked':''}> Enable X.com scanning</label><p class="small">Searches run daily at 06:17 UTC. Enabling takes effect at the next scheduled run. Disabling prevents further searches; checks of saved candidates can continue.</p><p class="small">Scans use available free or purchased X API credits. Set your spending limit and auto-recharge preferences in the X Developer Console. The collector keeps a $2 balance reserve and reads at most 50 posts per run.</p><button class="button" type="submit">Save X.com scanning</button>${settings.enabled?` <button class="button outline" id="x-scan-now" type="button" ${scanPending?'disabled':''}>Scan now</button>`:''}<p id="x-collection-message" role="status"></p></form><p class="small"><a href="https://github.com/sparx1981/reposhelf-x-collector/actions/workflows/collect.yml" target="_blank" rel="noopener">View scan history and results ↗</a>. Manual searches also require this toggle to be enabled.</p><div id="x-pipeline-progress" aria-live="polite"><p class="small">Loading scan progress.</p></div>`;
void loadProgress();
const scanButton=document.querySelector('#x-scan-now');if(scanButton)scanButton.onclick=async()=>{if(scanPending||!A.user?.admin)return;scanPending=true;scanButton.disabled=true;const message=document.querySelector('#x-collection-message');message.textContent='Requesting an X scan…';try{const result=await A.request('/api/editorial?action=x-scan',{method:'POST',body:'{}'});if(token!==epoch||!A.user?.admin)return;message.textContent=result.reason;requestedAt=result.requested===true?(result.requestedAt||new Date().toISOString()):null;void loadProgress();scanPending=result.requested===true||Boolean(result.activeRunId);}catch(error){if(token!==epoch||!A.user?.admin)return;message.textContent=error.message;scanPending=error.code==='x_dispatch_unconfirmed';}finally{scanButton.disabled=scanPending;}};
document.querySelector('#x-collection-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button'),message=form.querySelector('[role="status"]'),enabled=form.querySelector('input').checked;button.disabled=true;message.textContent='Saving…';
try{await A.request('/api/editorial?action=x-settings',{method:'POST',body:JSON.stringify({revision:settings.revision,enabled})});if(token!==epoch||!A.user?.admin)return;await load();const current=document.querySelector('#x-collection-message');if(current)current.textContent=enabled?'Saved. Scanning is enabled for the next scheduled run.':'Saved. New X searches are disabled.';}
catch(error){if(token!==epoch||!A.user?.admin)return;message.textContent=error.message;if(error.status===409)void load();}finally{button.disabled=false;}};
}catch(error){if(token!==epoch||!A.user?.admin)return;slot.innerHTML=error.code==='migration_required'?'<p>Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610080027_x_collection_settings.sql" target="_blank" rel="noopener">migration 27</a> to use the scanning toggle. X searches stay disabled until setup is complete.</p>':U.errorHtml(error.message,'x-collection');}}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function stamp(value){return value?new Date(value).toLocaleString():'Not yet recorded'}
function runState(run,available=true){return available===false?'History unavailable':!run?'No run recorded':run.status!=='completed'?run.status.replaceAll('_',' '):run.conclusion==='success'?'Complete':run.conclusion||'Finished'}
async function loadProgress(){const target=document.querySelector('#x-pipeline-progress');if(progressPending||!target||!A.user?.admin)return;progressPending=true;const token=epoch;try{const data=await A.request('/api/editorial?action=x-progress');if(token!==epoch||!A.user?.admin||!target.isConnected)return;const counts=data.counts,collection=counts?.collection,validation=counts?.validation,intake=data.intake;
 const stages=[['Collection',runState(data.collection,data.historyAvailable?.collection)],['Import',data.import&&data.import.status!=='completed'&&data.collection&&data.collection.status!=='completed'?'Waiting for collection':runState(data.import,data.historyAvailable?.import)],['Publication',data.publication?.status==='published'?'Published':data.publication?.status==='not_needed'?'No accepted changes to publish':data.publication?.status==='awaiting_publication'?'Awaiting publication':'Awaiting import']];
 target.innerHTML='<h4>Latest X scan</h4><dl class="project-facts">'+stages.map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+esc(value)+'</dd></div>').join('')+'</dl>'+(collection?'<p class="small">Last search '+esc(stamp(collection.at))+': <strong>'+Number(collection.postsRead||0)+' posts read</strong> · '+(collection.newCandidates===null?'New repository count unavailable':Number(collection.newCandidates||0)+' new repositories found')+' · '+Number(collection.candidateCount||0)+' saved candidates'+(collection.stopped?' · Stopped: '+esc(collection.stopped.replaceAll('_',' ')):'')+'.</p>':'<p class="small">Scan counts will appear after the updated collector saves its next checkpoint.</p>')+(validation?'<p class="small"><strong>'+Number(validation.qualityReady||0)+' quality-ready repositories</strong> in the saved list; '+Number(validation.checked||0)+' checked in that validation run ('+esc(stamp(validation.at))+').'+(!data.countsCurrent?' These are previous saved results.':'')+'</p>':'')+(intake?'<p class="small">Last import '+esc(stamp(intake.checkedAt))+': <strong>'+Number(intake.accepted||0)+' imported or updated</strong> · '+Number(intake.held||0)+' held for retry or moderation.</p>':'<p class="small">No import result recorded yet.</p>')+'<p class="small">Last publication: '+esc(stamp(data.publication?.lastPublishedAt))+'. Collection and import run outside the website server.</p><button type="button" class="button outline" id="x-progress-refresh">Refresh scan status</button>';
 document.querySelector('#x-progress-refresh').onclick=()=>void loadProgress();
 if(scanPending&&data.collection?.status==='completed'&&(!requestedAt||Date.parse(data.collection.createdAt)>=Date.parse(requestedAt)-5000)&&(!data.import||data.import.status==='completed')){scanPending=false;const button=document.querySelector('#x-scan-now');if(button)button.disabled=false;}
 }catch(error){if(token===epoch&&A.user?.admin&&target.isConnected)target.innerHTML='<p class="small" role="status">Scan status unavailable: '+esc(error.message)+'</p><button type="button" class="button outline" id="x-progress-refresh">Retry scan status</button>';document.querySelector('#x-progress-refresh')?.addEventListener('click',()=>void loadProgress());}finally{progressPending=false}}
setInterval(()=>{if(A.user?.admin&&!document.hidden&&!document.querySelector('#sync-panel')?.hidden)void loadProgress()},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!document.querySelector('#sync-panel')?.hidden)void loadProgress()});
document.addEventListener('click',event=>{if(event.target.closest('[data-admin-tab="sync"], [data-retry="x-collection"]'))void load();});
window.addEventListener('reposhelf-account',()=>{epoch++;settings=null;scanPending=false;if(!A.user?.admin)slot.innerHTML='';else if(new URL(location.href).searchParams.get('tab')==='sync')void load();});
if(A.user?.admin&&(new URL(location.href).searchParams.get('tab')==='sync'))void load();
})();
